package edu.riara.edp.week09;
import javafx.application.Application;import javafx.concurrent.Task;import javafx.scene.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.Stage;
public class BackgroundTaskDemo extends Application {public void start(Stage s){Label status=new Label("Ready");Button button=new Button("Process");button.setOnAction(e->{Task<String> task=new Task<>(){protected String call()throws Exception{Thread.sleep(2000);return "Finished without blocking";}};status.setText("Processing");button.setDisable(true);task.setOnSucceeded(event->{status.setText(task.getValue());button.setDisable(false);});task.setOnFailed(event->{status.setText("Failed");button.setDisable(false);});Thread t=new Thread(task);t.setDaemon(true);t.start();});s.setScene(new Scene(new VBox(15,status,button),460,170));s.show();}public static void main(String[]a){launch(a);}}